CREATE OR REPLACE FUNCTION public.affiliates_release_stale_duplicate_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_email text := old.historical_email_normalized;
  v_row public.affiliates%rowtype;
  v_count integer;
begin
  if v_email is null then return null; end if;
  if tg_op = 'UPDATE' and new.historical_email_normalized is not distinct from v_email then return null; end if;

  select count(*) into v_count from public.affiliates where historical_email_normalized = v_email;
  if v_count <> 1 then return null; end if;

  select * into v_row from public.affiliates where historical_email_normalized = v_email for update;
  if v_row.auth_user_id is not null
    or v_row.auth_eligibility <> 'duplicate_email'
    or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then
    return null;
  end if;

  update public.affiliates
  set auth_eligibility = 'eligible', auth_ineligibility_reason = null
  where id = v_row.id;

  insert into public.affiliate_access_repairs(
    action, actor_auth_user_id, affiliate_id, source_affiliate_id,
    before_state, after_state, reason
  ) values (
    'ELIGIBILITY_AUTO_RELEASED', auth.uid(), v_row.id, old.id,
    jsonb_build_object('auth_eligibility', 'duplicate_email'),
    jsonb_build_object('auth_eligibility', 'eligible'),
    'Automático: el correo dejó de estar duplicado'
  );

  if auth.uid() is not null then
    insert into public.affiliate_admin_events(
      affiliate_id, actor_auth_user_id, action, before_values, after_values, changed_fields, reason
    ) values (
      v_row.id, auth.uid(), 'UPDATE',
      jsonb_build_object('acceso_app', 'Bloqueado por correo duplicado'),
      jsonb_build_object('acceso_app', 'Puede activar su cuenta'),
      array['acceso_app'],
      'Acceso a la app · bloqueo retirado automáticamente: el correo ya no está en el control '
        || coalesce(old.numero_control, 'sin número')
    );
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.capture_savings_process_change_from_affiliate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old_process text;v_new_process text;v_participant record;v_enrollment record;v_plan jsonb;
begin
  v_old_process:=case old.financial_employee_category_code
    when 'SUPLENTES_VARIABLES' then 'PROCESS_3' when 'JUBILADOS_PENSIONADOS' then 'JUB'
    when 'SUPLENTES_FIJOS' then 'PROCESS_1' when 'EVENTUALES' then 'PROCESS_1' when 'BASE' then 'PROCESS_1' else null end;
  v_new_process:=case new.financial_employee_category_code
    when 'SUPLENTES_VARIABLES' then 'PROCESS_3' when 'JUBILADOS_PENSIONADOS' then 'JUB'
    when 'SUPLENTES_FIJOS' then 'PROCESS_1' when 'EVENTUALES' then 'PROCESS_1' when 'BASE' then 'PROCESS_1' else null end;
  if v_new_process is null or v_new_process is not distinct from v_old_process then return new; end if;
  select * into v_participant from public.savings_participants where affiliate_id=new.id;
  if not found then return new; end if;
  select * into v_enrollment from public.savings_enrollments
    where participant_id=v_participant.id and status in ('ACTIVE','TERMINATION_PENDING')
    order by sequence_number desc limit 1;
  if found then
    select to_jsonb(p) into v_plan from public.savings_contribution_plans p
      where p.enrollment_id=v_enrollment.id order by p.effective_from desc limit 1;
  end if;
  insert into public.savings_process_change_events(
    participant_id,affiliate_id,legacy_folio,old_process,new_process,status,current_plan_snapshot,reason,actor_real_auth_user_id
  ) values(
    v_participant.id,new.id,v_participant.legacy_folio,coalesce(v_participant.current_process,v_old_process),v_new_process,
    case when v_enrollment.id is null then 'NO_ACTIVE_ENROLLMENT' else 'SAVINGS_PROCESS_CHANGE_REVIEW_REQUIRED' end,
    coalesce(v_plan,'{}'::jsonb),'Cambio detectado desde Admin Afiliados',auth.uid()
  );
  update public.savings_participants set current_process=v_new_process,process_source='SHADOW' where id=v_participant.id;
  insert into public.savings_audit_events(actor_real_auth_user_id,usuario_contexto_affiliate_id,participant_id,resource,action,target_id,before_data,after_data,reason)
  values(auth.uid(),new.id,v_participant.id,'affiliates.financial_employee_category_code','PROCESS_CHANGE_DETECTED',new.id::text,
    jsonb_build_object('category',old.financial_employee_category_code,'process',coalesce(v_participant.current_process,v_old_process)),
    jsonb_build_object('category',new.financial_employee_category_code,'process',v_new_process),'Plan hist�rico sin modificar; revisi�n futura requerida');
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.change_admin_affiliate_control(p_affiliate_id uuid, p_new_control text, p_expected_updated_at timestamp with time zone, p_expected_fingerprint text, p_reason text, p_client_action_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare person public.affiliates%rowtype; report jsonb; saved public.affiliate_control_changes%rowtype;
begin
 perform public.affiliate_control_authorize();
 if p_client_action_id is null or length(coalesce(p_reason,''))>500 then raise exception 'AFFILIATE_CONTROL_INPUT_INVALID' using errcode='22023'; end if;
 -- Serialize with ordinary create/edit as well, including concurrent creations
 -- of the desired number. No global unique constraint on historical numbers.
 lock table public.affiliates in share row exclusive mode;
 select * into saved from public.affiliate_control_changes where client_action_id=p_client_action_id;
 if saved.id is not null then
  if saved.affiliate_id<>p_affiliate_id or saved.new_control is distinct from p_new_control
   or saved.actor_auth_user_id<>auth.uid() or saved.reason is distinct from coalesce(p_reason,'')
  then raise exception 'AFFILIATE_CONTROL_ACTION_CONFLICT' using errcode='22023'; end if;
  return jsonb_build_object('change',to_jsonb(saved),'replayed',true);
 end if;
 select * into person from public.affiliates where id=p_affiliate_id for update;
 if person.id is null then raise exception 'AFFILIATE_NOT_FOUND' using errcode='P0001'; end if;
 if person.updated_at is distinct from p_expected_updated_at then raise exception 'AFFILIATE_VERSION_CONFLICT' using errcode='PT409'; end if;
 report:=public.preview_admin_affiliate_control(p_affiliate_id,p_new_control);
 if jsonb_array_length(report->'blockers')>0 then raise exception 'AFFILIATE_CONTROL_BLOCKED' using errcode='22023'; end if;
 if report->>'fingerprint' is distinct from p_expected_fingerprint then raise exception 'AFFILIATE_CONTROL_IMPACT_CHANGED' using errcode='PT409'; end if;
 update public.affiliates set numero_control=p_new_control,
  financial_profile_version=financial_profile_version+1,
  financial_profile_updated_at=now(),financial_profile_updated_by=auth.uid(),updated_at=clock_timestamp()
 where id=person.id;
 insert into public.affiliate_control_changes(affiliate_id,actor_auth_user_id,old_control,new_control,reason,impact,client_action_id)
 values(person.id,auth.uid(),person.numero_control,p_new_control,coalesce(p_reason,''),report,p_client_action_id)
 returning * into saved;
 insert into public.affiliate_admin_events(affiliate_id,actor_auth_user_id,action,before_values,after_values,changed_fields,reason)
 values(person.id,auth.uid(),'UPDATE',jsonb_build_object('numero_control',person.numero_control),
  jsonb_build_object('numero_control',p_new_control,'control_change_id',saved.id),array['numero_control'],coalesce(p_reason,''));
 return jsonb_build_object('change',to_jsonb(saved),'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.create_admin_affiliate(p_values jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.affiliates%rowtype;v_duplicates jsonb;v_email text;v_eligibility text;v_reason text:=btrim(coalesce(p_reason,''));
  v_status text:=nullif(btrim(p_values->>'affiliate_status_raw'),'');
begin
  if not public.has_admin_permission('affiliates.write') then raise exception 'AFFILIATE_WRITE_DENIED' using errcode='42501'; end if;
  if jsonb_typeof(p_values)<>'object' then raise exception 'AFFILIATE_VALUES_REQUIRED' using errcode='22023'; end if;
  if length(v_reason)>500 then raise exception 'AFFILIATE_REASON_TOO_LONG' using errcode='22023'; end if;
  if length(btrim(coalesce(p_values->>'numero_control',''))) not between 1 and 80 then raise exception 'AFFILIATE_CONTROL_REQUIRED' using errcode='22023'; end if;
  if length(btrim(coalesce(p_values->>'full_name',''))) not between 3 and 240 then raise exception 'AFFILIATE_NAME_REQUIRED' using errcode='22023'; end if;
  if v_status is null or not exists(select 1 from public.affiliates where affiliate_status_raw=v_status) then raise exception 'AFFILIATE_STATUS_INVALID' using errcode='22023'; end if;
  if nullif(btrim(p_values->>'financial_union_code'),'') is not null and not exists(select 1 from public.segmentation_catalog_entries where catalog_type='union' and code=p_values->>'financial_union_code' and enabled) then raise exception 'AFFILIATE_UNION_INVALID' using errcode='22023'; end if;
  if nullif(btrim(p_values->>'financial_employee_category_code'),'') is not null and not exists(select 1 from public.segmentation_catalog_entries where catalog_type='employment_category' and code=p_values->>'financial_employee_category_code' and enabled) then raise exception 'AFFILIATE_CATEGORY_INVALID' using errcode='22023'; end if;
  v_duplicates:=public.find_admin_affiliate_duplicates(p_values,null);
  if exists(select 1 from jsonb_array_elements(v_duplicates) d(value) where (d.value->'matches') ?| array['numero_control','rfc','curp']) then
    raise exception 'AFFILIATE_DUPLICATE_REVIEW_REQUIRED' using errcode='23505';
  end if;
  v_email:=nullif(lower(btrim(p_values->>'historical_email_raw')),'');
  v_eligibility:=case when v_email is null then 'missing_email' when v_email!~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then 'invalid_email'
    when exists(select 1 from public.affiliates where historical_email_normalized=v_email) then 'duplicate_email' else 'eligible' end;
  insert into public.affiliates(
    numero_control,full_name,display_name,affiliate_status_raw,historical_email_raw,historical_email_normalized,phone_raw,address_raw,
    birth_date_raw,gender_raw,marital_status_raw,children_count_raw,rfc_raw,curp_raw,unit_raw,city_raw,employment_position_raw,
    employment_entry_date_raw,occupation_raw,institute_entry_date_raw,employment_area_raw,employment_level_raw,pension_raw,subdirectorate_raw,
    union_enrollment_date_raw,capture_date_raw,affiliation_raw,union_position_raw,termination_date_raw,financial_union_code,
    financial_employee_category_code,financial_employee_type,financial_affiliation_status,financial_employment_status,
    auth_eligibility,auth_ineligibility_reason,record_origin,source_row_ordinal,source_file_hash
  ) values(
    btrim(p_values->>'numero_control'),btrim(p_values->>'full_name'),nullif(btrim(p_values->>'display_name'),''),v_status,
    nullif(btrim(p_values->>'historical_email_raw'),''),v_email,nullif(btrim(p_values->>'phone_raw'),''),nullif(btrim(p_values->>'address_raw'),''),
    nullif(btrim(p_values->>'birth_date_raw'),''),nullif(btrim(p_values->>'gender_raw'),''),nullif(btrim(p_values->>'marital_status_raw'),''),nullif(btrim(p_values->>'children_count_raw'),''),
    nullif(upper(btrim(p_values->>'rfc_raw')),''),nullif(upper(btrim(p_values->>'curp_raw')),''),nullif(btrim(p_values->>'unit_raw'),''),nullif(btrim(p_values->>'city_raw'),''),
    nullif(btrim(p_values->>'employment_position_raw'),''),nullif(btrim(p_values->>'employment_entry_date_raw'),''),nullif(btrim(p_values->>'occupation_raw'),''),nullif(btrim(p_values->>'institute_entry_date_raw'),''),
    nullif(btrim(p_values->>'employment_area_raw'),''),nullif(btrim(p_values->>'employment_level_raw'),''),nullif(btrim(p_values->>'pension_raw'),''),nullif(btrim(p_values->>'subdirectorate_raw'),''),
    nullif(btrim(p_values->>'union_enrollment_date_raw'),''),nullif(btrim(p_values->>'capture_date_raw'),''),nullif(btrim(p_values->>'affiliation_raw'),''),nullif(btrim(p_values->>'union_position_raw'),''),
    nullif(btrim(p_values->>'termination_date_raw'),''),nullif(btrim(p_values->>'financial_union_code'),''),nullif(btrim(p_values->>'financial_employee_category_code'),''),
    nullif(btrim(p_values->>'financial_employee_type'),''),nullif(btrim(p_values->>'financial_affiliation_status'),''),nullif(btrim(p_values->>'financial_employment_status'),''),
    v_eligibility,case when v_eligibility='eligible' then null else v_eligibility end,'ADMIN_AFFILIATES',null,null
  ) returning * into v_row;
  insert into public.affiliate_admin_events(affiliate_id,actor_auth_user_id,action,before_values,after_values,changed_fields,reason)
  values(v_row.id,auth.uid(),'CREATE',null,to_jsonb(v_row)-array['auth_user_id','historical_email_normalized','source_file_hash']::text[],
    array['numero_control','full_name','affiliate_status_raw'],v_reason);
  return public.get_admin_affiliate_workbench(v_row.id);
end $function$

CREATE OR REPLACE FUNCTION public.get_admin_affiliate_workbench(p_affiliate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_profile jsonb;v_options jsonb;v_documents jsonb;v_requests jsonb;v_audit jsonb;
  v_can_documents boolean;v_can_requests boolean;
begin
  if not public.has_admin_permission('affiliates.read') then raise exception 'AFFILIATE_READ_DENIED' using errcode='42501'; end if;
  v_can_documents:=document_retirement_private.authorized() or public.has_admin_permission('documents.read') or public.has_admin_permission('assets.read');
  v_can_requests:=public.has_admin_permission('program_requests.read');
  select (to_jsonb(a)-array['auth_user_id','historical_email_normalized','source_file_hash','source_row_ordinal','financial_profile_updated_by','financial_profile_seed_source_hash','financial_profile_seed_row_ordinal']::text[])
    || jsonb_build_object('auth_linked',a.auth_user_id is not null)
  into v_profile from public.affiliates a where a.id=p_affiliate_id;
  if v_profile is null then raise exception 'AFFILIATE_NOT_FOUND' using errcode='P0001'; end if;
  select coalesce(jsonb_object_agg(catalog_type,items),'{}'::jsonb) into v_options from (
    select catalog_type,jsonb_agg(jsonb_build_object('code',code,'label',label) order by sort_order,label) items
    from public.segmentation_catalog_entries where enabled and catalog_type in('union','employment_category') group by catalog_type
  ) q;
  if v_can_documents then
    select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'type_id',d.document_type_id,'type_code',t.code,'type_label',t.label,
      'required',t.required_by_default,'status',d.status,'observation',d.review_observation,'created_at',d.created_at,'updated_at',d.updated_at)
      order by d.created_at desc),'[]'::jsonb) into v_documents
    from document_retirement_private.active_documents d join public.document_types t on t.id=d.document_type_id where d.affiliate_id=p_affiliate_id;
  end if;
  if v_can_requests then
    select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'folio',x.folio,'program_id',x.program_id,'request_type',x.request_type,
      'status',x.status,'financial_processing_status',x.financial_processing_status,'created_at',x.created_at,'updated_at',x.updated_at)
      order by x.created_at desc),'[]'::jsonb) into v_requests
    from (select * from public.program_requests where affiliate_id=p_affiliate_id order by created_at desc limit 50) x;
  end if;
  select coalesce(jsonb_agg(event order by event_at desc),'[]'::jsonb) into v_audit from (
    select e.created_at event_at,jsonb_build_object('id',e.event_id,'at',e.created_at,'action',e.action,'reason',e.reason,
      'actor',e.actor_auth_user_id,'changed_fields',e.changed_fields,'before',e.before_values,'after',e.after_values) event
    from public.affiliate_admin_events e where e.affiliate_id=p_affiliate_id
    union all
    select l.changed_at,jsonb_build_object('id',l.id,'at',l.changed_at,'action','PROFILE_FIELD_CHANGE','reason',l.reason,
      'actor',l.changed_by,'changed_fields',array[l.field_name],'before',jsonb_build_object(l.field_name,l.old_value),
      'after',jsonb_build_object(l.field_name,l.new_value))
    from public.affiliate_profile_audit_log l where l.affiliate_id=p_affiliate_id
    union all
    select o.created_at,jsonb_build_object('id',o.id,'at',o.created_at,'action','ADMIN_DOCUMENT_DELETE','reason',o.reason,'actor',o.actor_auth_user_id,'changed_fields',array['documents'],'before',jsonb_build_object('document_id',o.document_id),'after',jsonb_build_object('status',case when o.completed_at is null then 'PENDING_STORAGE' else 'COMPLETE' end)) from document_retirement_private.operations o where o.affiliate_id=p_affiliate_id
  ) q;
  return jsonb_build_object('profile',v_profile,'options',v_options,'documents',v_documents,'requests',v_requests,'audit',v_audit,
    'document_summary',jsonb_build_object('required_count',(select count(*) from public.document_types where enabled and required_by_default),'verified_required_count',(select count(*) from public.document_types t join lateral (select d.* from document_retirement_private.active_documents d where d.affiliate_id=p_affiliate_id and d.document_type_id=t.id order by d.created_at desc,d.id desc limit 1) latest on true left join public.affiliate_files af on af.id=latest.affiliate_file_id join public.private_assets pa on pa.id=coalesce(latest.private_asset_id,af.private_asset_id) and pa.status='READY' where t.enabled and t.required_by_default and latest.status='VERIFIED' and exists(select 1 from storage.objects so where so.bucket_id=pa.storage_bucket and so.name=pa.storage_path))),'empty_document_slots',coalesce((select jsonb_agg(s) from (select distinct d.document_type_id type_id,t.label type_label from document_retirement_private.documents r join public.affiliate_documents d on d.id=r.document_id join public.document_types t on t.id=d.document_type_id where d.affiliate_id=p_affiliate_id and not exists(select 1 from document_retirement_private.active_documents current_doc where current_doc.affiliate_id=p_affiliate_id and current_doc.document_type_id=d.document_type_id)) s),'[]'::jsonb),'pending_document_deletions',case when document_retirement_private.authorized() then coalesce((select jsonb_agg(jsonb_build_object('operation_id',o.id,'document_id',o.document_id,'created_at',o.created_at)) from document_retirement_private.operations o where o.affiliate_id=p_affiliate_id and o.completed_at is null),'[]'::jsonb) else '[]'::jsonb end,'capabilities',jsonb_build_object('documents',v_can_documents,'requests',v_can_requests));
end $function$

CREATE OR REPLACE FUNCTION public.list_admin_affiliates(p_query text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_auth_linked boolean DEFAULT NULL::boolean, p_document_state text DEFAULT NULL::text, p_has_pending_documents boolean DEFAULT NULL::boolean, p_union_code text DEFAULT NULL::text, p_category_code text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 25, p_sort text DEFAULT 'name'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_query text:=lower(btrim(coalesce(p_query,'')));v_page integer:=greatest(coalesce(p_page,1),1);v_page_size integer:=least(greatest(coalesce(p_page_size,25),10),100);v_result jsonb;
begin
  if not public.has_admin_permission('affiliates.read') then raise exception 'AFFILIATE_READ_DENIED' using errcode='42501'; end if;
  if p_document_state is not null and upper(p_document_state) not in('COMPLETE','INCOMPLETE','NOT_CONFIGURED') then raise exception 'AFFILIATE_DOCUMENT_FILTER_INVALID' using errcode='22023'; end if;
  if coalesce(p_sort,'name') not in('name','control','recent') then raise exception 'AFFILIATE_SORT_INVALID' using errcode='22023'; end if;
  with required as(select count(*)::integer required_count from public.document_types where enabled and required_by_default),
  docs as(select d.affiliate_id,count(*) filter(where d.status<>'REJECTED')::integer document_count,count(*) filter(where d.status in('PENDING_REVIEW','UNDER_REVIEW','REUPLOAD_REQUIRED'))::integer pending_document_count,count(distinct d.document_type_id) filter(where d.status='VERIFIED' and t.enabled and t.required_by_default)::integer verified_required_count from document_retirement_private.active_documents d join public.document_types t on t.id=d.document_type_id group by d.affiliate_id),
  requests as(select r.affiliate_id,count(*)::integer request_count,count(*) filter(where r.status in('submitted','in_review','requires_financial_processing'))::integer pending_request_count from public.program_requests r group by r.affiliate_id),
  base as(select a.id,a.numero_control,a.full_name,a.display_name,a.historical_email_raw,a.phone_raw,a.rfc_raw,a.curp_raw,a.affiliate_status_raw,a.affiliation_raw,a.financial_union_code,a.financial_employee_category_code,a.financial_affiliation_status,a.financial_employment_status,a.updated_at,a.record_origin,(a.auth_user_id is not null) auth_linked,coalesce(d.document_count,0) document_count,coalesce(d.pending_document_count,0) pending_document_count,coalesce(d.verified_required_count,0) verified_required_count,required.required_count,case when required.required_count=0 then 'NOT_CONFIGURED' when coalesce(d.verified_required_count,0)>=required.required_count then 'COMPLETE' else 'INCOMPLETE' end document_state,coalesce(r.request_count,0) request_count,coalesce(r.pending_request_count,0) pending_request_count,lower(coalesce(a.full_name,a.display_name,'')) sort_name from public.affiliates a cross join required left join docs d on d.affiliate_id=a.id left join requests r on r.affiliate_id=a.id where not a.is_archived),
  filtered as(select * from base b where (v_query='' or position(v_query in lower(concat_ws(' ',b.full_name,b.display_name,b.numero_control,b.historical_email_raw,b.phone_raw,b.rfc_raw,b.curp_raw)))>0) and (p_status is null or b.affiliate_status_raw=p_status) and (p_auth_linked is null or b.auth_linked=p_auth_linked) and (p_document_state is null or b.document_state=upper(p_document_state)) and (p_has_pending_documents is null or (b.pending_document_count>0)=p_has_pending_documents) and (p_union_code is null or b.financial_union_code=p_union_code) and (p_category_code is null or b.financial_employee_category_code=p_category_code)),
  page_rows as(select * from filtered order by case when p_sort='control' then coalesce(numero_control,'') end,case when p_sort='recent' then updated_at end desc,case when p_sort='name' then sort_name end,sort_name,id offset (v_page-1)*v_page_size limit v_page_size)
  select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(x)-'sort_name') from(select * from page_rows)x),'[]'::jsonb),'total',(select count(*) from filtered),'page',v_page,'page_size',v_page_size,'filter_options',jsonb_build_object('statuses',coalesce((select jsonb_agg(value order by value) from(select distinct affiliate_status_raw value from public.affiliates where not is_archived and affiliate_status_raw is not null and btrim(affiliate_status_raw)<>'')s),'[]'::jsonb),'unions',coalesce((select jsonb_agg(jsonb_build_object('code',code,'label',label) order by sort_order,label) from public.segmentation_catalog_entries where catalog_type='union' and enabled),'[]'::jsonb),'categories',coalesce((select jsonb_agg(jsonb_build_object('code',code,'label',label) order by sort_order,label) from public.segmentation_catalog_entries where catalog_type='employment_category' and enabled),'[]'::jsonb))) into v_result;
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.list_admin_archived_affiliates(p_query text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 25, p_sort text DEFAULT 'recent'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_query text:=lower(btrim(coalesce(p_query,'')));v_page integer:=greatest(coalesce(p_page,1),1);v_page_size integer:=least(greatest(coalesce(p_page_size,25),10),100);v_result jsonb;
begin
  if not public.has_admin_permission('affiliates.read') then raise exception 'AFFILIATE_READ_DENIED' using errcode='42501'; end if;
  if coalesce(p_sort,'recent') not in('name','control','recent') then raise exception 'AFFILIATE_SORT_INVALID' using errcode='22023'; end if;
  with docs as(select affiliate_id,count(*)::integer document_count from document_retirement_private.active_documents group by affiliate_id),requests as(select affiliate_id,count(*)::integer request_count from public.program_requests group by affiliate_id),base as(
    select a.id,a.numero_control,a.full_name,a.display_name,a.historical_email_raw,a.rfc_raw,a.curp_raw,a.affiliate_status_raw,a.archive_previous_status_raw,a.archived_at,a.archived_by_auth_user_id,a.archive_reason,a.updated_at,a.record_origin,(a.auth_user_id is not null) auth_linked,coalesce(d.document_count,0) document_count,coalesce(r.request_count,0) request_count,lower(coalesce(a.full_name,a.display_name,'')) sort_name
    from public.affiliates a left join docs d on d.affiliate_id=a.id left join requests r on r.affiliate_id=a.id where a.is_archived
  ),filtered as(select * from base b where v_query='' or position(v_query in lower(concat_ws(' ',b.full_name,b.display_name,b.numero_control,b.historical_email_raw,b.rfc_raw,b.curp_raw)))>0),page_rows as(
    select * from filtered order by case when p_sort='control' then coalesce(numero_control,'') end,case when p_sort='recent' then archived_at end desc,case when p_sort='name' then sort_name end,sort_name,id offset (v_page-1)*v_page_size limit v_page_size)
  select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(x)-'sort_name') from(select * from page_rows)x),'[]'::jsonb),'total',(select count(*) from filtered),'page',v_page,'page_size',v_page_size,'filter_options','{}'::jsonb) into v_result;
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.preview_admin_affiliate_control(p_affiliate_id uuid, p_new_control text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare person public.affiliates%rowtype; report jsonb; blocks jsonb:='[]'; link_risk boolean:=false;
begin
 perform public.affiliate_control_authorize();
 select * into person from public.affiliates where id=p_affiliate_id;
 if person.id is null then raise exception 'AFFILIATE_NOT_FOUND' using errcode='P0001'; end if;
 if person.is_archived then raise exception 'AFFILIATE_ARCHIVED' using errcode='22023'; end if;
 if p_new_control is null or length(p_new_control) not between 1 and 80 or p_new_control<>btrim(p_new_control)
  or p_new_control ~ '[[:cntrl:]]' then raise exception 'AFFILIATE_CONTROL_INVALID' using errcode='22023'; end if;
 if person.numero_control is not distinct from p_new_control then raise exception 'AFFILIATE_NO_CHANGE' using errcode='22023'; end if;
 if exists(select 1 from public.affiliates where id<>person.id and numero_control=p_new_control)
  or exists(select 1 from public.affiliate_control_changes where affiliate_id<>person.id
   and (old_control=p_new_control or new_control=p_new_control))
 then blocks:=blocks||jsonb_build_array('NUMBER_ALREADY_ASSIGNED'); end if;
 report:=public.affiliate_control_inventory(person.id,person.numero_control,p_new_control);
 if exists(select 1 from jsonb_array_elements(report->'groups') g where (g->>'new_number_conflicts')::bigint>0)
 then blocks:=blocks||jsonb_build_array('NUMBER_HAS_UNRELATED_RECORDS'); end if;
 -- A historical CSV certification can be the only valid login proof. Never
 -- silently invalidate it, nor rewrite historical certification to make it fit.
 select exists(select 1 from auth.users u where u.id=person.auth_user_id
  and public.has_certified_affiliate_auth_link(u.id,person.id,u.email)
  and (person.historical_email_normalized is distinct from lower(btrim(u.email))
   or (select count(*) from public.affiliates a where a.historical_email_normalized=lower(btrim(u.email)))<>1)) into link_risk;
 if link_risk then blocks:=blocks||jsonb_build_array('ACCESS_REPAIR_REQUIRED'); end if;
 report:=report||jsonb_build_object('affiliate_id',person.id,'old_control',person.numero_control,
  'new_control',p_new_control,'expected_updated_at',person.updated_at,'blockers',blocks,
  'automatic_changes',jsonb_build_array('Número vigente del afiliado','Invalidación de cotizaciones anteriores'),
  'manual_review_required',true);
 return report||jsonb_build_object('fingerprint',md5(report::text));
end $function$

